#!/bin/sh
# Generate the reports, then upload them to S3 if S3_BUCKET is set
set -e
/rpmwatcher/rpmwatcher.py --output /out --cache /cache --index-root "/$S3_PREFIX" "$@"
if [ -n "$S3_BUCKET" ]; then
    AWS="aws ${S3_ENDPOINT_URL:+--endpoint-url $S3_ENDPOINT_URL}"
    $AWS s3 sync --no-progress /out "s3://$S3_BUCKET/$S3_PREFIX"
    # the list of versions also includes the ones not generated by this run (archives)
    versions=$($AWS s3 ls "s3://$S3_BUCKET/$S3_PREFIX" | awk '$1 == "PRE" { print $2 }')
    /rpmwatcher/autoindex.py /tmp/index.html "/$S3_PREFIX" $versions
    $AWS s3 cp --no-progress /tmp/index.html "s3://$S3_BUCKET/${S3_PREFIX}index.html"
fi
